INSERT IGNORE INTO `__公会战配置表` VALUES
(1001, '绑定事件编号', '0', '这个事件属于核心管理 不与功能事件冲突 所以不能超过100 使用该功能确保只能有两个公会 总控有限制玩家创建公会的'),
(1002, '公会战申请需求模版', '0', '活动开始后 将由公会的成员去NPC申请提交进攻的需求'),
(1003, '胜利方公会拍卖行比例', '0.3', '根据胜利公会胜利期间直到下一次挑战失败的获益'),
(1004, '胜利方公会奖励礼包', '49426', '胜利后会发邮件给会长 由于是邮件机制 防止会长掉线没有 所以改成礼包'),
(1005, '参与胜利方奖励模版', '0', '这是公会成员都有的奖励-胜利 当场发放的 前提满足1017或1018'),
(1006, '参与失败方奖励模版', '0', '这是公会成员都有的奖励-失败 当场发放的 前提满足1017或1018'),
(1007, '胜利资源点数', '3000', '资源点 显示在界面上的 类似阿拉希那种'),
(1008, '每秒资源奖励', '50', '如果没达到胜利点则活动结束按最多的算 例如: 防守方在资源点附近清除所有敌对后 每秒得到的点数 反之亦然'),
(1009, '防守方BUFF', '', '留空=无 以#隔开 光环做成不消失的 由核心控制附加或移除 基于活动逻辑'),
(1010, '进攻方BUFF', '', '留空=无 以#隔开 光环做成不消失的 由核心控制附加或移除 基于活动逻辑'),
(1011, '平衡BUFF', '0', '0=无 此项是单个光环 做成不消失可叠加的 默认先不叠加 由核心根据连胜机制控制叠加多少'),
(1012, '资源点旗帜GUID', '0', '一面旗帜或者雕像之类的 以此作为争夺的基准 为0活动会不生效'),
(1013, '资源点旗帜坐标', '109', '参考坐标模版'),
(1014, '资源点范围半径', '30', '以此来判断是否能获得资源点 即这个半径内没有敌人和己方人员在此范围内'),
(1015, '进攻方入场的坐标', '107', '参考坐标模版'),
(1016, '防守方入场的坐标', '108', '参考坐标模版'),
(1017, '获得奖励最低治疗量', '0', '0=不限制'),
(1018, '获得奖励最低伤害量', '0', '0=不限制'),
(1019, '进攻方资源提示界面编号', '18000', 'WorldStateUI.dbc 的编号'),
(1020, '防守方资源提示界面编号', '18001', 'WorldStateUI.dbc 的编号'),
(1021, '弹框传送出现的文字', '|n[公会争霸战]|n现在已经开始 你们被分配为 [%s] 点击接受进入战斗|n', '');
