INSERT IGNORE INTO `__全服对战配置表` VALUES
(5001, '绑定事件编号', '94', '这个事件属于核心管理 不与功能事件冲突 所以不能超过100 用来启动管理活动的基准'),
(5002, '活动开始后全服弹框传送出现的文字', '|n[全服资源争霸战]-[联盟VS部落]|n现在已经开始 使用混排机制 点击接受进入或从NPC处进入|n', ''),
(5003, '联盟方入场的坐标模版', '214', '参考坐标模版'),
(5004, '部落方入场的坐标模版', '215', '参考坐标模版'),
(5005, '联盟方BUFF', '', '留空=无 以#隔开 光环做成不消失的 由核心控制附加或移除 基于活动逻辑'),
(5006, '部落方BUFF', '', '留空=无 以#隔开 光环做成不消失的 由核心控制附加或移除 基于活动逻辑'),
(5007, '进入活动后分配阵营时的提示文字', '你被分配到 [%s] 方 请尽量杀敌争取胜利', ''),
(5008, '胜利资源点数', '2000', '资源点 显示在界面上的 类似阿拉希那种'),
(5009, '每秒资源奖励', '5', '如果没达到胜利点则活动结束按最多的算 例如: 在资源点附近清除所有敌对后 每秒得到的点数 反之亦然'),
(5010, '活动所在的地区编号 ZoneId', '4384', '必须设置正确 否则活动无效'),
(5011, '资源点旗帜GUID', '2136653', '一面旗帜或者雕像之类的 以此作为争夺的基准 为0活动会不生效 需要预先去那个位置刷出来 放那得到GUID 之后就不用管了 永久存在'),
(5012, '资源点涨点奖励范围半径', '10', '以此来判断是否能获得资源点 即这个半径内没有敌人和己方人员在此范围内'),
(5031, '联盟方资源提示界面编号', '18000', 'WorldStateUI.dbc 的编号'),
(5032, '部落方资源提示界面编号', '18001', 'WorldStateUI.dbc 的编号'),
(5041, '获得奖励最低治疗量', '0', '0=不限制'),
(5042, '获得奖励最低伤害量', '2000', '0=不限制'),
(5043, '胜利方奖励模版', '346', '胜利 当场发放的 前提满足5041或5042'),
(5044, '失败方奖励模版', '347', '失败 当场发放的 前提满足5041或5042'),
(5055, '容错机制 如果活动时间结束 分数一样 则算哪边赢', '0', '0=都不奖励 1=联盟 2=部落 这个情况出现的概率很小 随便配置就行了'),
(6000, '无效配置 只是用来说明', '以上的联盟或者部落 并非游戏里本身的联盟或部落阵营 是活动开始之后分配的联盟或部落 中途退出重进也是之前的阵营', ''),
(6001, '无效配置 只是用来说明', '根据平衡填充混排相关机制 首先会保证两边人数尽量一致 所以可能会使得你是联盟的也会被分配到联盟 反之亦然 对战注重的是分配后的阵营 并非原始阵营', ''),
(6002, '无效配置 只是用来说明', '关于中途退出的 再次想进来 到主城找NPC对话进入 脚本名 NpcAsPlayerBattle', '');
