INSERT IGNORE INTO `_1v1竞技场配置表` VALUES
(11, '是否启用', '1', '1=开0=关'),
(12, '绑定事件编号', '0', '0=不限制 大于0表示仅在事件期间开启'),
(13, '创建或排队需要角色等级', '80', '0=不限制 如果不限制注意PvpDifficulty.dbc'),
(14, '是否允许观战', '1', '1=开0=关 观战中不能攻击/施法/聊天 小退或自然对阵胜负即可结束观战'),
(15, '排队是否全服公告', '1', '1=开0=关'),
(16, '匹配策略积分差值', '0', '0=不限制 如果大于0 举例 当前玩家积分是1500 差值是500 那么将会匹配到 1500±500 即1000-2000分段的人 前提是级别一致'),
(17, '创建队伍初始给的积分值', '1000', '跟官方配置文件不冲突'),
(18, '赢奖励模版', '0', '0=无 对应 __模版奖励总表'),
(19, '输奖励模版', '0', '0=无 对应 __模版奖励总表'),
(20, '是否限制某些天赋专精或技能光环排队进入', '1', '0=不限制 1=限制'),
(21, '限制的天赋专精列表', '201#202', '留空不限制 以#隔开 这里填写的是天赋的专精编号 TalentTab.dbc的ID 例如牧师的戒律是201神圣是202'),
(22, '限制的天赋专精投入的点数', '36', '0=不限制 在这个天赋专精点了大于等于36点 就被限制'),
(23, '限制的技能光环列表', '', '留空不限制 以#隔开 技能或光环编号'),
(24, '创建竞技场队伍需求模版', '0', '0=无 防止创建后解散无脑创建得分'),
(25, '同一个玩家在事件内进场次数(若绑定事件)', '3', '0=不限制 大于0=次数');
